import json

def solve():
    input_str = "( { < { ( ( { } ) ( ) ) } { } < { } > < > > } { } ( { ( { { } } ) [ ( ) ] } ) ) [ ( [ ]"
    tokens = input_str.split()

    matching = {
        '(': ')',
        '{': '}',
        '[': ']',
        '<': '>'
    }

    closing = {v: k for k, v in matching.items()}

    stack = []
    for token in tokens:
        if token in matching:
            stack.append(token)
        elif token in closing:
            if not stack or stack[-1] != closing[token]:
                raise ValueError(f"Mismatched token: {token}")
            stack.pop()
        else:
            raise ValueError(f"Unknown token: {token}")

    # Complete by closing the remaining items in reverse order
    completion = [matching[op] for op in reversed(stack)]
    final_answer = " ".join(completion)

    print(json.dumps({
        "final_answer": final_answer,
        "evidence": f"Unclosed stack: {stack}, required closing tokens: {completion}"
    }))

if __name__ == "__main__":
    solve()
